"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useId, useState } from "react";

import {
  CircleCheckIcon,
  RefreshIcon,
  SparklesIcon,
} from "@/components/blocks/parts/icons";
import { SegmentedControl } from "@/components/motion/segmented-control";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import {
  GROUPS,
  ITEMS,
  RANGES,
  type RangeId,
  SOURCE_IDS,
  SOURCES,
} from "./catch-up/data";
import { DigestItem } from "./catch-up/digest-item";
import { useTicker } from "./lib/use-ticker";
import { countAllWords, revealParts } from "./lib/words";

type View = "sources" | "digest" | "outcome";

const WORDS_PER_TICK = 3;

/**
 * A welcome-back digest. Pick a range, let the assistant read the connected
 * tools, and the ranked updates stream in, each with Open and Mark as read.
 * Sources, digest and the all-read outcome swap with one crossfade.
 */
export function CatchUp({ className }: { className?: string }) {
  const reduceMotion = useReducedMotion();
  const [range, setRange] = useState<RangeId>("3");
  const [view, setView] = useState<View>("sources");
  const [read, setRead] = useState<string[]>([]);
  const [opened, setOpened] = useState<string | null>(null);
  const titleId = useId();

  const inRange = ITEMS.filter((item) => item.daysAgo < Number(range));
  const unread = inRange.filter((item) => !read.includes(item.id));
  // The stream runs over every update in range, read or not, so reading one never pushes the others ahead.
  const all = GROUPS.flatMap((group) =>
    inRange.filter((item) => item.group === group.id),
  );
  const ordered = all.filter((item) => !read.includes(item.id));
  const sentences = all.map((item) => item.sentence);
  const stream = useTicker(
    Math.ceil(
      countAllWords(ITEMS.map((item) => item.sentence)) / WORDS_PER_TICK,
    ),
    70,
  );
  const shown = revealParts(sentences, stream.tick * WORDS_PER_TICK);
  const streaming =
    stream.running && shown.some((text, index) => text !== sentences[index]);

  const readTools = () => {
    setRead([]);
    setOpened(null);
    setView("digest");
    stream.start();
  };

  const changeRange = (next: RangeId) => {
    setRange(next);
    if (view !== "sources") readTools();
  };

  const markRead = (id: string) => {
    const next = [...read, id];
    setRead(next);
    if (inRange.every((item) => next.includes(item.id))) setView("outcome");
  };

  const fade = reduceMotion ? { duration: 0 } : { duration: 0.18 };
  const headline =
    view === "outcome"
      ? "You are all caught up"
      : view === "digest"
        ? `${unread.length} updates while you were away`
        : "Welcome back, Priya";

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-5 py-4">
        <div className="min-w-0">
          <h2
            id={titleId}
            className="text-base font-semibold"
            aria-live="polite"
          >
            {headline}
          </h2>
          <p className="text-sm text-muted-foreground">
            Fernhill, Harbour Street clinic
          </p>
        </div>
        <SegmentedControl
          aria-label="Catch up on"
          options={RANGES}
          value={range}
          onValueChange={changeRange}
        />
      </header>

      <div className="scroll-fade-effect-y scrollbar-none relative grid h-112 overflow-y-auto">
        <AnimatePresence mode="wait" initial={false}>
          <motion.div
            key={view}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={fade}
            className="col-start-1 row-start-1 min-w-0"
          >
            {view === "sources" ? (
              <div className="flex h-full flex-col justify-center gap-5 px-5 py-6">
                <p className="max-w-sm text-sm text-muted-foreground">
                  The assistant reads your connected tools for the last{" "}
                  {RANGES.find((item) => item.value === range)?.label} and ranks
                  what needs you first.
                </p>
                <ul className="grid grid-cols-2 gap-2 @md:grid-cols-4">
                  {SOURCE_IDS.map((id) => (
                    <li
                      key={id}
                      className="flex items-center gap-2.5 rounded-lg border border-border px-3 py-2.5"
                    >
                      <span
                        aria-hidden="true"
                        className={cn(
                          "flex size-7 items-center justify-center rounded-md text-xs font-semibold",
                          SOURCES[id].tint,
                        )}
                      >
                        {SOURCES[id].name[0]}
                      </span>
                      <span className="flex min-w-0 flex-col">
                        <span className="truncate text-sm font-medium">
                          {SOURCES[id].name}
                        </span>
                        <span className="text-xs text-muted-foreground tabular-nums">
                          {inRange.filter((item) => item.source === id).length}{" "}
                          updates
                        </span>
                      </span>
                    </li>
                  ))}
                </ul>
                <Button className="self-start" onClick={readTools}>
                  <SparklesIcon aria-hidden="true" className="size-4" />
                  Catch me up
                </Button>
              </div>
            ) : null}

            {view === "digest" ? (
              <div
                aria-busy={streaming}
                className="flex flex-col gap-4 px-3 py-4"
              >
                {GROUPS.map((group) => {
                  const items = ordered.filter(
                    (item) => item.group === group.id,
                  );
                  if (items.length === 0) return null;
                  return (
                    <section
                      key={group.id}
                      aria-labelledby={`${titleId}-${group.id}`}
                      className="flex flex-col gap-1"
                    >
                      <h3
                        id={`${titleId}-${group.id}`}
                        className="flex items-center gap-2 px-2 text-xs font-medium text-muted-foreground"
                      >
                        <span
                          aria-hidden="true"
                          className={cn("size-2 rounded-full", group.dot)}
                        />
                        {group.label}
                        <span className="tabular-nums">{items.length}</span>
                      </h3>
                      <ul className="flex flex-col">
                        <AnimatePresence initial={false}>
                          {items.map((item) => (
                            <DigestItem
                              key={item.id}
                              item={item}
                              shown={shown[all.indexOf(item)] ?? ""}
                              streaming={streaming}
                              onOpen={() => setOpened(item.reference)}
                              onRead={() => markRead(item.id)}
                            />
                          ))}
                        </AnimatePresence>
                      </ul>
                    </section>
                  );
                })}
              </div>
            ) : null}

            {view === "outcome" ? (
              <div className="flex h-full flex-col items-center justify-center gap-3 px-5 text-center">
                <CircleCheckIcon
                  aria-hidden="true"
                  className="size-8 text-marketing-green-ink"
                />
                <p className="max-w-xs text-sm text-muted-foreground">
                  You read {inRange.length} updates. New ones will wait here
                  until you come back.
                </p>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setView("sources")}
                >
                  Back to sources
                </Button>
              </div>
            ) : null}
          </motion.div>
        </AnimatePresence>
      </div>

      <footer className="flex flex-wrap items-center justify-between gap-3 border-t border-border px-5 py-3">
        <p
          role="status"
          className="min-w-0 truncate text-sm text-muted-foreground"
        >
          {opened
            ? `Opened ${opened}`
            : streaming
              ? "Reading your tools"
              : view === "digest"
                ? `${read.length} of ${inRange.length} read`
                : "4 tools connected"}
        </p>
        <div className="flex gap-2">
          {view === "digest" ? (
            <>
              <Button
                variant="ghost"
                size="sm"
                onClick={readTools}
                disabled={streaming}
              >
                <RefreshIcon aria-hidden="true" className="size-4" />
                Read again
              </Button>
              <Button
                variant="outline"
                size="sm"
                disabled={streaming}
                onClick={() => {
                  setRead(inRange.map((item) => item.id));
                  setView("outcome");
                }}
              >
                Mark all as read
              </Button>
            </>
          ) : null}
        </div>
      </footer>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

