import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

/** A connected tool the digest reads from. */
export type SourceId = "calendar" | "inbox" | "ledger" | "huddle";

/** How a digest item ranks: what needs the reader comes first. */
export type GroupId = "needs" | "decided" | "done" | "fyi";

/** One update in the digest. */
export interface CatchUpItem {
  id: string;
  group: GroupId;
  source: SourceId;
  /** Days ago it happened, 0 for today. */
  daysAgo: number;
  sentence: string;
  people: string[];
  /** Where the update lives, such as a ticket number. */
  reference: string;
}

/** The ranges a reader can catch up on. */
export type RangeId = "1" | "3" | "7";

/** The range choices. */
export const RANGES: { value: RangeId; label: string }[] = [
  { value: "1", label: "1 day" },
  { value: "3", label: "3 days" },
  { value: "7", label: "1 week" },
];

/** Each connected tool, with the tint of its mark. */
export const SOURCES = {
  calendar: {
    name: "Calendar",
    tint: "bg-marketing-blue-surface text-marketing-blue-ink",
  },
  inbox: {
