import { motion, useReducedMotion } from "motion/react";

import { CheckIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { ArrowUpRightIcon } from "../icons";
import { Initials } from "../parts/initials";
import { StreamingText } from "../parts/streaming-text";
import { type CatchUpItem, PEOPLE, SOURCES } from "./data";

/** Props for one update in the digest. */
export interface DigestItemProps {
  item: CatchUpItem;
  /** The part of the sentence streamed so far. Empty shows quiet skeleton bars in the reserved space. */
  shown: string;
  streaming: boolean;
  onOpen: () => void;
  onRead: () => void;
}

/**
 * One update: its tool mark, the sentence, the people and the reference,
 * then Open and Mark as read. The row keeps its full height while the
 * sentence streams, and collapses smoothly once it is read.
 */
export function DigestItem({
  item,
  shown,
  streaming,
  onOpen,
  onRead,
}: DigestItemProps) {
  const reduceMotion = useReducedMotion();
  const source = SOURCES[item.source];
  const ready = shown === item.sentence;

  return (
    <motion.li
      layout={reduceMotion ? false : "position"}
      initial={false}
      exit={
        reduceMotion
          ? { opacity: 0, transition: { duration: 0 } }
          : {
              opacity: 0,
              height: 0,
              transition: { duration: 0.22, ease: [0.4, 0, 0.2, 1] },
            }
      }
      className="overflow-hidden"
    >
      <div className="group relative isolate grid grid-cols-[1.75rem_1fr_auto] gap-x-3 rounded-lg px-2 py-2.5">
        <span
          aria-hidden="true"
          className="absolute inset-0 -z-10 rounded-lg group-hover:bg-muted group-focus-within:bg-muted"
        />
        <span
          aria-hidden="true"
          className={cn(
            "mt-0.5 flex size-7 items-center justify-center rounded-md text-xs font-semibold",
            source.tint,
          )}
        >
          {source.name[0]}
        </span>
        <div className="flex min-w-0 flex-col gap-1.5">
          <div className="relative text-sm">
            <StreamingText
              full={item.sentence}
              shown={shown}
              streaming={streaming && !ready && shown !== ""}
            />
            {shown === "" ? (
              <span
                aria-hidden="true"
                className="absolute inset-0 flex flex-col gap-2 pt-1"
              >
                <span className="h-2.5 w-11/12 rounded-full bg-muted" />
                <span className="h-2.5 w-7/12 rounded-full bg-muted" />
              </span>
            ) : null}
          </div>
          <p
            className={cn(
              "flex min-w-0 items-center gap-2 text-xs text-muted-foreground motion-safe:transition-opacity",
              ready ? "opacity-100" : "opacity-0",
            )}
          >
            <span className="sr-only">From {source.name}.</span>
            {item.people.length > 0 ? (
              <span className="flex -space-x-1.5">
                {item.people.map((person) => (
                  <Initials
                    key={person}
                    name={person}
                    tint={PEOPLE.indexOf(person)}
                    className="size-5 text-xs"
                  />
                ))}
              </span>
            ) : null}
            <span className="truncate">
              {item.people.length > 0 ? (
                <span className="sr-only">{item.people.join(" and ")}, </span>
              ) : null}
              {item.reference}
            </span>
          </p>
        </div>
        <div className="flex items-start gap-0.5">
          <Button
            variant="ghost"
            size="icon"
            className="size-8"
            aria-label={`Open ${item.reference}`}
            disabled={!ready}
            onClick={onOpen}
          >
            <ArrowUpRightIcon aria-hidden="true" />
          </Button>
          <Button
            variant="ghost"
            size="icon"
            className="size-8"
            aria-label={`Mark ${item.reference} as read`}
            disabled={!ready}
            onClick={onRead}
          >
            <CheckIcon aria-hidden="true" className="size-4" />
          </Button>
        </div>
      </div>
    </motion.li>
  );
}

